/**
 * What the HTTP API and the CLI both do: making accounts and tokens,
 * storing, describing and deleting images (file + database row).
 *
 * Image files live in `<data>/images/<id>.<ext>` and the thumbnail in
 * `<data>/images/<id>.thumb.<ext>`; ids are generated by the server
 * (tokens.ts `newId`) and checked against `ID_RE` before a path is built, so
 * no client text ever becomes part of a path.
 */

import { mkdirSync, renameSync, rmSync, writeFileSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ApiError, bad } from './http.ts';
import {
  type Account, type Db, type ImageRow, countTokens, getAccount, insertAccount, insertImage, insertToken, now,
} from './db.ts';
import { type CleanImage, cleanImage, ImageError } from './imagefile.ts';
import { ID_RE, TOKEN_RE, hashToken, newId, newToken, tokenPrefix } from './tokens.ts';

export const NAME_MAX = 40;

export function validName(v: unknown): string {
  if (typeof v !== 'string') throw bad('name must be a string');
  const s = v.replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩]/g, '').trim();
  if (s.length < 1 || s.length > NAME_MAX) throw bad(`name must have 1 to ${NAME_MAX} characters`);
  return s;
}

/** Adds a token to an account: the custom one if given (validated, must be unused) or a new random one. */
export function addToken(db: Db, pepper: string, account: string, custom?: unknown): string {
  if (custom !== undefined && custom !== null) {
    if (typeof custom !== 'string' || !TOKEN_RE.test(custom)) {
      throw bad('a token must have 8 to 128 letters, digits, "-", "_" or "."', 'bad_token_format');
    }
    if (!insertToken(db, account, hashToken(pepper, custom), tokenPrefix(custom))) {
      throw new ApiError(409, 'token_taken', 'this token is already in use');
    }
    return custom;
  }
  if (countTokens(db, account) >= 50) throw new ApiError(409, 'too_many_tokens', 'an account may have at most 50 tokens');
  for (;;) {
    const t = newToken();
    if (insertToken(db, account, hashToken(pepper, t), tokenPrefix(t))) return t;
  }
}

/** Makes an account with one token; the transaction leaves nothing behind when the custom token is taken. */
export function createAccount(db: Db, pepper: string, name: unknown, opts: { admin?: boolean; token?: unknown } = {}): { account: Account; token: string } {
  const n = validName(name);
  db.exec('BEGIN');
  try {
    const account = insertAccount(db, { id: newId(), name: n, admin: !!opts.admin });
    const token = addToken(db, pepper, account.id, opts.token);
    db.exec('COMMIT');
    return { account, token };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export const publicAccount = (a: Account) => ({ id: a.id, name: a.name, admin: a.admin, created: a.created });

// ---------------------------------------------------------------- images

export const imagesDir = (dataDir: string): string => join(dataDir, 'images');

function safeId(id: string): string {
  if (!ID_RE.test(id)) throw new Error('bad image id');
  return id;
}

const EXT: Record<string, string> = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };

export function imagePath(dataDir: string, id: string, mime: string): string {
  return join(imagesDir(dataDir), `${safeId(id)}.${EXT[mime] ?? 'bin'}`);
}

export function thumbPath(dataDir: string, id: string, mime: string): string {
  return join(imagesDir(dataDir), `${safeId(id)}.thumb.${EXT[mime] ?? 'bin'}`);
}

function writeAtomic(path: string, data: Buffer): void {
  const tmp = `${path}.tmp-${process.pid}`;
  writeFileSync(tmp, data, { mode: 0o640 });
  renameSync(tmp, path);
}

export interface ImageMetaIn {
  lat: number;
  lon: number;
  heading?: number;
  pitch?: number;
  kind: 'photo' | 'pano360';
  taken?: string;
  title?: string;
  visibility: 'private' | 'public';
}

export const THUMB_MAX_SIDE = 1024;

/** Strips, checks and stores an image (and an optional client-made thumbnail); returns the database row. */
export function storeImage(
  db: Db, dataDir: string, owner: string, meta: ImageMetaIn, file: Buffer, thumb: Buffer | null,
): ImageRow {
  let img: CleanImage;
  let th: CleanImage | null = null;
  try {
    img = cleanImage(file);
    if (thumb) th = cleanImage(thumb);
  } catch (e) {
    if (e instanceof ImageError) throw new ApiError(415, 'bad_image', e.message);
    throw e;
  }
  if (meta.kind === 'pano360') {
    const tol = Math.max(2, img.width * 0.005);
    if (Math.abs(img.width - 2 * img.height) > tol) {
      throw new ApiError(422, 'not_equirectangular', 'a 360° panorama must be twice as wide as high (2:1)');
    }
  }
  if (th && (th.width > THUMB_MAX_SIDE || th.height > THUMB_MAX_SIDE)) {
    throw new ApiError(422, 'thumb_too_big', `a thumbnail may be at most ${THUMB_MAX_SIDE} pixels wide and high`);
  }
  mkdirSync(imagesDir(dataDir), { recursive: true });
  const id = newId();
  const t = now();
  const row: ImageRow = {
    id, owner, kind: meta.kind, lat: meta.lat, lon: meta.lon, heading: meta.heading ?? null, pitch: meta.pitch ?? null,
    taken: meta.taken ?? null, title: meta.title ?? '', visibility: meta.visibility, mime: img.mime,
    width: img.width, height: img.height, bytes: img.data.length, thumb_mime: th ? th.mime : null, created: t, updated: t,
  };
  writeAtomic(imagePath(dataDir, id, img.mime), img.data);
  if (th) writeAtomic(thumbPath(dataDir, id, th.mime), th.data);
  try {
    insertImage(db, row);
  } catch (e) {
    removeImageFiles(dataDir, row);
    throw e;
  }
  return row;
}

export function removeImageFiles(dataDir: string, r: Pick<ImageRow, 'id' | 'mime' | 'thumb_mime'>): void {
  rmSync(imagePath(dataDir, r.id, r.mime), { force: true });
  if (r.thumb_mime) rmSync(thumbPath(dataDir, r.id, r.thumb_mime), { force: true });
}

export function readImageFile(dataDir: string, r: ImageRow, thumb: boolean): Buffer | null {
  try {
    if (thumb) return r.thumb_mime ? readFileSync(thumbPath(dataDir, r.id, r.thumb_mime)) : null;
    return readFileSync(imagePath(dataDir, r.id, r.mime));
  } catch {
    return null;
  }
}

/** Removes the files of images whose rows are already gone (account deletion). */
export function removeImageFilesById(dataDir: string, ids: string[]): void {
  for (const id of ids) {
    if (!ID_RE.test(id)) continue;
    for (const ext of ['jpg', 'png', 'webp']) {
      rmSync(join(imagesDir(dataDir), `${id}.${ext}`), { force: true });
      rmSync(join(imagesDir(dataDir), `${id}.thumb.${ext}`), { force: true });
    }
  }
}

export function imageJson(db: Db, r: ImageRow, names?: Map<string, string>) {
  let ownerName = names?.get(r.owner);
  if (ownerName === undefined) {
    ownerName = getAccount(db, r.owner)?.name ?? '';
    names?.set(r.owner, ownerName);
  }
  return {
    id: r.id, owner: r.owner, ownerName, kind: r.kind, lat: r.lat, lon: r.lon, heading: r.heading, pitch: r.pitch,
    taken: r.taken, title: r.title, visibility: r.visibility, type: r.mime, width: r.width, height: r.height,
    bytes: r.bytes, created: r.created, updated: r.updated,
    file: `/api/v1/images/${r.id}/file`, thumb: r.thumb_mime ? `/api/v1/images/${r.id}/thumb` : null,
  };
}

/** Validates the `meta` of an upload (or of a PATCH when `partial`). */
export function parseImageMeta(v: unknown, partial: boolean): Partial<ImageMetaIn> {
  if (!v || typeof v !== 'object' || Array.isArray(v)) throw bad('meta must be a JSON object', 'bad_meta');
  const m = v as Record<string, unknown>;
  const out: Partial<ImageMetaIn> = {};
  const num = (k: string, min: number, max: number, required: boolean): number | undefined => {
    const x = m[k];
    if (x === undefined || x === null) {
      if (required) throw bad(`meta.${k} is required`, 'bad_meta');
      return undefined;
    }
    if (typeof x !== 'number' || !Number.isFinite(x) || x < min || x > max) throw bad(`meta.${k} must be a number from ${min} to ${max}`, 'bad_meta');
    return x;
  };
  out.lat = num('lat', -90, 90, !partial);
  out.lon = num('lon', -180, 180, !partial);
  out.heading = num('heading', -360, 360, false);
  out.pitch = num('pitch', -90, 90, false);
  if (m.kind !== undefined) {
    if (partial) throw bad('the kind of an image cannot be changed', 'bad_meta');
    if (m.kind !== 'photo' && m.kind !== 'pano360') throw bad('meta.kind must be "photo" or "pano360"', 'bad_meta');
    out.kind = m.kind;
  } else if (!partial) throw bad('meta.kind is required', 'bad_meta');
  if (m.visibility !== undefined) {
    if (m.visibility !== 'private' && m.visibility !== 'public') throw bad('meta.visibility must be "private" or "public"', 'bad_meta');
    out.visibility = m.visibility;
  } else if (!partial) out.visibility = 'private';
  if (m.title !== undefined && m.title !== null) {
    if (typeof m.title !== 'string') throw bad('meta.title must be a string', 'bad_meta');
    const t = m.title.replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
    if (t.length > 200) throw bad('meta.title may have at most 200 characters', 'bad_meta');
    out.title = t;
  }
  if (m.taken !== undefined && m.taken !== null) {
    const t = typeof m.taken === 'string' && m.taken.length <= 40 ? Date.parse(m.taken) : NaN;
    if (!Number.isFinite(t)) throw bad('meta.taken must be an ISO-8601 time', 'bad_meta');
    out.taken = new Date(t).toISOString();
  }
  return out;
}
